    {
      "rank": 1,
      "ballot_id": "B019",
      "proposed_laureates": [
        "Christopher Jarzynski",
        "Denis J. Evans",
        "Udo Seifert"
      ],
      "assessment": {
        "nobel_worthiness": "A deep, experimentally relevant extension of statistical mechanics that identifies universal constraints on fluctuations far from equilibrium.",
        "attribution": "Evans initiated fluctuation relations; Jarzynski supplied a transformative equality; Seifert established much of the stochastic-thermodynamic framework. Crooks is also central, making the three-person limit difficult.",
        "maturity": "The results have been broadly tested and have become a durable conceptual and practical framework.",
        "uncertainties": [
          "Credit is unusually distributed across several indispensable theoretical formulations."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Bertrand I. Halperin",
        "David R. Nelson",
        "A. Peter Young"
      ],
      "assessment": {
        "nobel_worthiness": "An elegant defect-based account of two-dimensional melting that exposed a genuinely distinctive phase-transition mechanism.",
        "attribution": "Halperin and Nelson developed the central theory, with Young providing the complementary renormalization-group treatment conventionally joined to it.",
        "maturity": "The theory has survived extensive numerical and experimental scrutiny and is foundational statistical physics.",
        "uncertainties": [
          "The detailed phenomenology of melting depends on microscopic system and can complicate a simple universal narrative."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B006",
      "proposed_laureates": [
        "John Toner",
        "Tamás Vicsek",
        "Yuhai Tu"
      ],
      "assessment": {
        "nobel_worthiness": "Collective motion revealed striking nonequilibrium order and supplied a broadly influential hydrodynamic theory of active matter.",
        "attribution": "Vicsek's model established the phenomenon, while Toner and Tu supplied its essential long-wavelength theoretical explanation.",
        "maturity": "The ideas have generated a major mature field and robust tests across synthetic and biological active systems.",
        "uncertainties": [
          "Real biological collectives may not always lie in the minimal-model universality class."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B028",
      "proposed_laureates": [
        "Antoine Georges",
        "Dieter Vollhardt",
        "Gabriel Kotliar"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory gave strongly correlated-electron physics a controlled and remarkably productive conceptual and computational framework.",
        "attribution": "Vollhardt's infinite-dimensional construction and the Georges-Kotliar formulation were decisive; the listed trio represents the core development fairly.",
        "maturity": "It is an established workhorse for correlated materials and has shaped both theory and interpretation of experiments.",
        "uncertainties": [
          "Its central approximation is exact only in a limiting setting, with nonlocal correlations requiring extensions."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B022",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum spin Hall prediction and topological-insulator program changed the classification of electronic phases and launched a large experimental field.",
        "attribution": "Kane and Mele provided the defining theoretical advance, and Molenkamp led landmark experimental realization of the quantum spin Hall effect.",
        "maturity": "The phase and its protected boundary physics are firmly established, with extensive experimental confirmation.",
        "uncertainties": [
          "The closely related discovery of three-dimensional topological insulators creates a substantial boundary-of-award and attribution question."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B024",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "John D. Joannopoulos",
        "Sajeev John"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic band gaps supplied a powerful wave-physics analogue of electronic band structure and enabled a far-reaching field of structured light.",
        "attribution": "John and Yablonovitch independently established key photonic-gap concepts, while Joannopoulos made foundational theoretical contributions to the field.",
        "maturity": "The phenomenon is established and has had lasting scientific and technological consequences.",
        "uncertainties": [
          "The balance between conceptual discovery, materials realization, and later applications is difficult to delimit."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks combine a clean physical principle with extraordinary precision, expanding both metrology and fundamental tests.",
        "attribution": "Katori introduced the magic-wavelength lattice-clock concept, and Ye made equally decisive experimental advances and realizations.",
        "maturity": "Performance, reproducibility, and scientific utility are thoroughly demonstrated.",
        "uncertainties": [
          "The eventual award scope may need to distinguish optical clocks from the wider precision-measurement ecosystem."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Juan Maldacena",
        "Edward Witten",
        "Alexander Polyakov"
      ],
      "assessment": {
        "nobel_worthiness": "Gauge/gravity duality is among the most profound modern theoretical unifications, with consequences extending beyond high-energy theory.",
        "attribution": "Maldacena formulated the decisive correspondence, while Witten and Polyakov made essential foundational contributions to the underlying framework.",
        "maturity": "Its internal theoretical impact is immense and continuing, though direct experimental confirmation remains absent.",
        "uncertainties": [
          "The lack of direct empirical confirmation is a serious consideration for a physics prize."
        ]
      }
    }
  ]
}
